// groupCost[k] is the price, in cents, of a group of k distinct books.
// Each book costs 800 cents, with discounts of 5%, 10%, 20% and 25%
// for groups of 2, 3, 4 and 5 distinct books respectively.
var groupCost = []int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the minimum total price, in cents, for the given basket of
// books, giving the biggest possible discount. Each book is identified by an
// integer from 1 to 5.
func Cost(books []int) int {
	counts := [5]int{}
	for _, b := range books {
		if b >= 1 && b <= 5 {
			counts[b-1]++
		}
	}
	return minCost(counts[:])
}

var memo = map[string]int{}

// minCost returns the minimum cost of a basket whose per-title counts are
// given by counts. The five titles are symmetric, so the state is fully
// described by the sorted count vector. Every possible group (a non-empty
// subset of the titles that still have copies) is tried, which guarantees
// the overall grouping is optimal.
func minCost(counts []int) int {
	sort.Ints(counts)
	key := string(rune(0)) // placeholder, replaced below
	_ = key
	key = makeKey(counts)
	if v, ok := memo[key]; ok {
		return v
	}

	// n is the number of titles with at least one remaining copy; because
	// counts is sorted ascending, those are indices 0..n-1.
	n := 0
	for i := len(counts) - 1; i >= 0; i-- {
		if counts[i] > 0 {
			n = i + 1
			break
		}
	}
	if n == 0 {
		memo[key] = 0
		return 0
	}

	best := int(^uint(0) >> 1)
	for mask := 1; mask < 1<<n; mask++ {
